42	  const { data, error } = await supabase
43	    .from('staff')
44	    .insert({
45	      facility_id:     facilityId,
46	      name:            staffData.name,
47	      role:            staffData.role,
48	      employment_type: staffData.employmentType,
49	      phone:           staffData.phone || null,
50	      email:           staffData.email || null,
51	      is_active:       true,
52	    })
53	    .select()
54	    .single();
55	  return { data, error };
56	}
