58	export async function updateStaff(staffId, updates) {
59	  const payload = {};
60	  if (updates.name !== undefined)           payload.name            = updates.name;
61	  if (updates.role !== undefined)           payload.role            = updates.role;
62	  if (updates.employmentType !== undefined) payload.employment_type = updates.employmentType;
63	  if (updates.phone !== undefined)          payload.phone           = updates.phone;
64	  if (updates.email !== undefined)          payload.email           = updates.email;
65	
66	  const { data, error } = await supabase
67	    .from('staff')
68	    .update(payload)
69	    .eq('id', staffId)
70	    .select()
71	    .single();
72	  return { data, error };
73	}
74	
75	export async function deleteStaff(staffId) {
76	  // Soft delete — mark inactive so shift history is preserved
77	  const { data, error } = await supabase
78	    .from('staff')
79	    .update({ is_active: false })
80	    .eq('id', staffId);
81	  return { data, error };
